static void compare(const Result&a,const Result&b){if(a.events!=b.events){for(size_t i=0;i<a.events.size()||i<b.events.size();i++){auto x=i<a.events.size()?a.events[i]:"<end>",y=i<b.events.size()?b.events[i]:"<end>";if(x!=y){std::fprintf(stderr,"event %zu native=%s candidate=%s\n",i,x.c_str(),y.c_str());break;}}}req(a.events==b.events,"callback order exact");if(a.states!=b.states){for(size_t i=0;i<a.states.size();i++)if(a.states[i]!=b.states[i]){std::fprintf(stderr,"snapshot %zu\nNATIVE\n%s\nGOOSE\n%s\n",i,a.states[i].c_str(),b.states[i].c_str());break;}}req(a.states==b.states,"placement split copy graph state exact");req(a.values==b.values,"numerical outputs exact");req(a.sizes==b.sizes,"reserved and physical buffer sizes exact");event_records+=a.events.size();}
